const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/**
 * Parses the election description from `input`, throwing a `CliError` at
 * the first problem the specification defines. Returns `{ candidates,
 * ballots }`, where `candidates` lists the declared names in the order they
 * were declared and each ballot is `{ count, names }`.
