export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail(lineNo, 'expected candidates <name>...')
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) fail(lineNo, `invalid candidate name ${name}`)
        if (seen.has(name)) fail(lineNo, `candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        fail(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        fail(lineNo, 'count must be a positive integer')
      }
      const declared = new Set(candidates)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!declared.has(name)) fail(lineNo, `unknown candidate ${name}`)
        if (seen.has(name)) fail(lineNo, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(countStr), names })
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    failNoLine('no candidates')
  }

  return { candidates, ballots }
}
"}

