{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-cR5DjO/src/election.js","content":"/**
 * Counts an election parsed by `parseElection`. Returns `{ rounds, winner }`,
 * where `winner` is a candidate name or `null` and each round is
 * `{ entries, exhausted, eliminated }`: `entries` lists every continuing
 * candidate as `{ name, count }` sorted by descending count then ascending
 * name, and `eliminated` is the name dropped after this round or `null`.
 */
export function runElection({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((name) => [name, []]))

  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0)

    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else counts.set(choice, counts.get(choice) + ballot.count)
    }

    for (const name of continuing) history.get(name).push(counts.get(name))

    const activeTotal = [...continuing].reduce((sum, name) => sum + counts.get(name), 0)

    const entries = [...continuing]
      .map((name) => ({ name, count: counts.get(name) }))
      .sort((a, b) => b.count - a.count || (a.name < b.name ? -1 : 1))

    const majorityWinner = activeTotal > 0
      ? [...continuing].find((name) => counts.get(name) * 2 > activeTotal)
      : undefined

    if (majorityWinner !== undefined) {
      winner = majorityWinner
      rounds.push({ entries, exhausted, eliminated: null })
      break
    }

    if (activeTotal === 0) {
      rounds.push({ entries, exhausted, eliminated: null })
      break
    }

    const minCount = Math.min(...[...continuing].map((name) => counts.get(name)))
    const tied = [...continuing].filter((name) => counts.get(name) === minCount)
    const eliminated = pickEliminated(tied, history)
    continuing.delete(eliminated)
    rounds.push({ entries, exhausted, eliminated })
  }

  return { rounds, winner }
}

/**
 * Breaks a tie for fewest votes by comparing the tied candidates' counts
 * round by round from the first round onwards, narrowing to whoever had
 * fewest at the first round where they differ and restarting the
 * comparison from the first round for the survivors. When no round
 * separates them, the name that sorts last by code point is eliminated.
 */
function pickEliminated(tiedNames, history) {
  let group = tiedNames
  const roundCount = history.get(group[0]).length

  while (group.length > 1) {
    let splitRound = -1
    for (let r = 0; r < roundCount; r++) {
      const first = history.get(group[0])[r]
      if (group.some((name) => history.get(name)[r] !== first)) {
        splitRound = r
        break
      }
    }
    if (splitRound === -1) break

    const values = group.map((name) => history.get(name)[splitRound])
    const min = Math.min(...values)
    group = group.filter((_, i) => values[i] === min)
  }

  if (group.length === 1) return group[0]
  return group.slice().sort().pop()
}
