    const entries = round.entries.map((e) => `${e.name}=${e.count}`).join(' ')
    output += `round ${index + 1}: ${entries} exhausted=${round.exhausted}\n`
    if (round.eliminated !== null) output += `eliminated ${round.eliminated}\n`
  })
